def f(a):
    out=[r[:] for r in a]; h,w=len(a),len(a[0]); br=None
    for i,r in enumerate(a):
        if 2 in r and 0<i<h-1: br=i; break
    top=[c for c in range(w) if a[0][c]!=0]
    bot=[c for c in range(w) if a[h-1][c]!=0]
    for c in set(top)&set(bot):
        for r in range(1,br): out[r][c]=4
        for r in range(br+1,h-1): out[r][c]=4
    return out
